"""Unsloth backend adapter.

Unsloth has no first-class CLI; it is driven through its Python API
(``FastLanguageModel.from_pretrained`` + a TRL ``SFTTrainer``). The dry-run
plan therefore emits (a) a runnable training script as an artifact and (b) a
``python -c`` style command summary, plus an ``api_call`` string.
"""

from __future__ import annotations

from ..base import TrainerBackend, TrainingPlan
from ..config import Precision, TrainingConfig
from ..registry import register_backend

_SCRIPT_TEMPLATE = '''\
# Auto-generated by kubeflow_llm_trainer (Unsloth backend)
from unsloth import FastLanguageModel
from trl import SFTTrainer, SFTConfig

model, tokenizer = FastLanguageModel.from_pretrained(
    model_name={model!r},
    max_seq_length={max_seq_len},
    load_in_4bit={load_in_4bit},
    load_in_8bit={load_in_8bit},
    dtype={dtype!r},
)
model = FastLanguageModel.get_peft_model(
    model,
    r={r},
    lora_alpha={alpha},
    lora_dropout={dropout},
    target_modules={target_modules!r},
    bias={bias!r},
)

from datasets import load_dataset
dataset = load_dataset({dataset!r}, split={split!r})

trainer = SFTTrainer(
    model=model,
    tokenizer=tokenizer,
    train_dataset=dataset,
    args=SFTConfig(
        output_dir={output_dir!r},
        per_device_train_batch_size={bs},
        gradient_accumulation_steps={ga},
        num_train_epochs={epochs},
        learning_rate={lr},
        warmup_ratio={warmup},
        weight_decay={wd},
        max_seq_length={max_seq_len},
        seed={seed},
        bf16={bf16},
        fp16={fp16},
    ),
)
trainer.train()
'''


@register_backend()
class UnslothBackend(TrainerBackend):
    name = "unsloth"
    required_dependency = "unsloth"

    def validate(self, cfg: TrainingConfig) -> None:
        # Unsloth is built around PEFT; full fine-tuning is out of scope here.
        if not cfg.lora.enabled:
            raise ValueError(
                "Unsloth backend requires lora.enabled=True (Unsloth is "
                "optimized for LoRA/QLoRA fine-tuning)."
            )

    def build_plan(self, cfg: TrainingConfig) -> TrainingPlan:
        hp = cfg.hyperparams
        load_in_4bit = cfg.precision == Precision.INT4
        load_in_8bit = cfg.precision == Precision.INT8
        bf16 = cfg.precision == Precision.BF16
        fp16 = cfg.precision == Precision.FP16
        dtype = None  # let Unsloth auto-detect unless quantized handled above

        target_modules = cfg.lora.target_modules or [
            "q_proj",
            "k_proj",
            "v_proj",
            "o_proj",
            "gate_proj",
            "up_proj",
            "down_proj",
        ]

        script = _SCRIPT_TEMPLATE.format(
            model=cfg.model_name_or_path,
            max_seq_len=hp.max_seq_len,
            load_in_4bit=load_in_4bit,
            load_in_8bit=load_in_8bit,
            dtype=dtype,
            r=cfg.lora.r,
            alpha=cfg.lora.alpha,
            dropout=cfg.lora.dropout,
            target_modules=target_modules,
            bias=cfg.lora.bias,
            dataset=cfg.dataset.name_or_path,
            split=cfg.dataset.split,
            output_dir=cfg.output_dir,
            bs=hp.per_device_batch_size,
            ga=hp.gradient_accumulation_steps,
            epochs=hp.num_epochs,
            lr=hp.learning_rate,
            warmup=hp.warmup_ratio,
            wd=hp.weight_decay,
            seed=hp.seed,
            bf16=bf16,
            fp16=fp16,
        )

        script_name = "unsloth_train.py"
        api_call = (
            f"FastLanguageModel.from_pretrained(model_name={cfg.model_name_or_path!r}, "
            f"max_seq_length={hp.max_seq_len}, load_in_4bit={load_in_4bit}) "
            f"-> get_peft_model(r={cfg.lora.r}, lora_alpha={cfg.lora.alpha}) "
            f"-> SFTTrainer(...).train()"
        )

        return TrainingPlan(
            backend=self.name,
            mode="api",
            command=["python", script_name],
            api_call=api_call,
            artifacts={script_name: script},
            resolved={
                "tool": "unsloth.FastLanguageModel + trl.SFTTrainer",
                "model": cfg.model_name_or_path,
                "dataset": cfg.dataset.name_or_path,
                "load_in_4bit": load_in_4bit,
                "load_in_8bit": load_in_8bit,
                "precision": cfg.precision.value,
                "lora_r": cfg.lora.r,
                "effective_batch_size": hp.effective_batch_size,
            },
            notes=[
                f"Dry-run would write '{script_name}' then run: python {script_name}",
                "Install with: pip install 'kubeflow-llm-trainer[unsloth]'",
            ],
        )
